// 校园调查。选择查阅地点后，只进入对应的场景。
function campusChoice(text, next, result, { blood = 0, spirit = 0, favor = 0, flags = [] } = {}) {
  return { text, next, result, blood, spirit, favor, flags, requiredSpirit: 0, requiredFlag: '' };
}

function campusChapter(title, paragraphs, choices) {
  return { title, text: paragraphs.join('\n\n'), choices, ending: false };
}

